25	static std::vector<int> toPrimeFactors(int x) {
26	  int i = 2;
27	  std::vector<int> result;
28	  while (x > 1) {
29	    if (x % i == 0) {
30	      x /= i;
31	      result.push_back(i);
32	    } else {
33	      i++;
34	    }
35	  }
36	  return result;
37	}
