64	std::pair<int, int> Gemm::ComputeWarpPartition(int num_warps, Target target,
65	                                               bool maybe_hopper_wgmma) const {
66	  int m_warp = 1, n_warp = 1;
67	  constexpr int kMPerWarp = 16; // Rows processed by a single warp
68	  constexpr int kNPerWarp = 8;  // Columns processed by a single warp
69	  bool allow_wgmma = TargetIsHopper(target) && maybe_hopper_wgmma &&
70	                     (this->M >= 64) && (num_warps % 4 == 0);
71	  if (allow_wgmma) {
72	    ICHECK(num_warps % 4 == 0) << "Warp-Group MMA requires 128×k threads.";
73	
74	    constexpr int kGroup = 4; // Number of warps in a warp-group
75	
76	    m_warp = kGroup; // Initially, only one warp-group on M dimension
77	    n_warp = num_warps / m_warp; // Rest all on N dimension
78	
79	    if (this->policy == GemmWarpPolicy::kFullRow) {
80	      // Try to put as many warp-groups as possible on M dimension
81	      // (decreasing multiples of 4, ensuring divisibility by M)
82	      for (int cand = num_warps; cand >= kGroup; cand -= kGroup) {
83	        if (this->M % (cand * kMPerWarp) == 0) {
84	          m_warp = cand;
85	          n_warp = num_warps / m_warp;
86	          break;
87	        }
88	      }
89	    } else if (this->policy == GemmWarpPolicy::kFullCol) {
90	      // Try to use warps on N dimension; if N is not divisible, split excess
91	      // groups to M
92	      int cand_n = n_warp;                       // Initially assume all on N
93	      if (this->N % (cand_n * kNPerWarp) != 0) { // N direction division fails
94	        int max_n = this->N / kNPerWarp;
95	        // Find a feasible n_warp from max possible downwards, ensuring
96	        // num_warps/n_warp is multiple of 4
97	        for (int n = std::min(cand_n, max_n); n >= 1; --n) {
98	          if (num_warps % n == 0 && (num_warps / n) % kGroup == 0) {
99	            n_warp = n;
100	            m_warp = num_warps / n_warp;
101	            break;
102	          }
103	        }
104	      }
105	    } else if (this->policy == GemmWarpPolicy::kSquare) {
106	      // Exhaustive search, but m must be multiple of 4
107	      int max_m = this->M / kMPerWarp;
108	      int max_n = this->N / kNPerWarp;
109	
110	      float ideal = this->N > 0 ? static_cast<float>(this->M) / this->N : 1.f;
111	
112	      float best_score = std::numeric_limits<float>::max();
113	      int best_m = kGroup, best_n = n_warp;
114	
115	      for (int m = kGroup; m <= num_warps && m <= max_m; m += kGroup) {
116	        if (num_warps % m)
117	          continue;
118	        int n = num_warps / m;
119	        if (n > max_n)
120	          continue;
121	
122	        float m_per_warp = static_cast<float>(this->M) / (m * kMPerWarp);
123	        float n_per_warp = static_cast<float>(this->N) / (n * kNPerWarp);
124	        float score = std::abs(m_per_warp / n_per_warp - ideal);
125	
126	        if (score < best_score) {
127	          best_score = score;
128	          best_m = m;
129	          best_n = n;
130	        }
131	      }
132	      m_warp = best_m;
133	      n_warp = best_n;
134	    } else {
135	      ICHECK(0) << "Unknown GemmWarpPolicy";
136	    }
137	
138	    ICHECK(m_warp * n_warp == num_warps)
139	        << "m_warp * n_warp must equal num_warps";
140	    return {m_warp, n_warp};
141	  }
142	
143	  if (this->policy == GemmWarpPolicy::kFullRow) {
144	    // Try to partition M first
145	    m_warp = num_warps;
146	    n_warp = 1;
147	
148	    // If M cannot be evenly divided by m_warp*16, try to split remaining warps
149	    // to N
150	    if (this->M % (m_warp * kMPerWarp) != 0) {
151	      // Calculate how many warps we can use for M
152	      int max_m_warps = this->M / kMPerWarp;
153	      m_warp = max_m_warps;
154	      // Use remaining warps for N
155	      n_warp = num_warps / m_warp;
156	      if (n_warp == 0)
157	        n_warp = 1;
158	    }
159	  } else if (this->policy == GemmWarpPolicy::kFullCol) {
160	    // Try to partition N first
161	    m_warp = 1;
162	    n_warp = num_warps;
163	
164	    // If N cannot be evenly divided by n_warp*8, try to split remaining warps
165	    // to M
166	    if (this->N % (n_warp * kNPerWarp) != 0) {
167	      // Calculate how many warps we can use for N
168	      int max_n_warps = this->N / kNPerWarp;
169	      n_warp = max_n_warps;
170	      // Use remaining warps for M
171	      m_warp = num_warps / n_warp;
172	      if (m_warp == 0)
173	        m_warp = 1;
174	    }
175	  } else if (this->policy == GemmWarpPolicy::kSquare) {
176	    // First calculate the maximum possible warps for each dimension
177	    int max_m_warps =
178	        this->M / kMPerWarp; // Each warp needs at least 16 elements in M
179	    int max_n_warps =
180	        this->N / kNPerWarp; // Each warp needs at least 8 elements in N
181	
182	    // Calculate the ideal ratio of M/N warps based on the matrix dimensions
183	    float ideal_ratio = 1.0f;
184	    if (this->N > 0) {
185	      ideal_ratio = static_cast<float>(this->M) / this->N;
186	    }
187	
188	    // Start with a balanced initial guess
189	    m_warp = 1;
190	    n_warp = 1;
191	
192	    // Try to find the best balanced partition
193	    int best_m = 1;
194	    int best_n = 1;
195	    float best_balance = std::numeric_limits<float>::max();
196	
197	    // Try all possible combinations that satisfy the constraints
198	    for (int m = 1; m <= max_m_warps && m <= num_warps; m++) {
199	      int n = num_warps / m;
200	      if (n > max_n_warps)
201	        continue;
202	      if (m * n != num_warps)
203	        continue;
204	
205	      // Calculate how balanced this partition is
206	      float m_per_warp = static_cast<float>(this->M) / (m * kMPerWarp);
207	      float n_per_warp = static_cast<float>(this->N) / (n * kNPerWarp);
208	      float balance = std::abs(m_per_warp / n_per_warp - ideal_ratio);
209	
210	      if (balance < best_balance) {
211	        best_balance = balance;
212	        best_m = m;
213	        best_n = n;
214	      }
215	    }
216	
217	    m_warp = best_m;
218	    n_warp = best_n;
219	  } else {
220	    ICHECK(0) << "Unknown GemmWarpPolicy";
221	  }
222	  return {m_warp, n_warp};
223	}
