225	Stmt Gemm::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
226	  int warp_size = 32;
227	  if (TargetIsCDNA(T.target)) {
228	    warp_size = 64;
229	  }
230	  auto block_size = *as_const_int(T.thread_bounds->extent);
231	  bool maybe_wgmma = TargetIsHopper(T.target) && (this->M >= 64) &&
232	                     (block_size / warp_size % 4 == 0);
233	
234	  auto [warp_m, warp_n] =
235	      ComputeWarpPartition(block_size / warp_size, T.target, maybe_wgmma);
236	
237	  std::stringstream ss;
238	  std::string op_name = "tl::gemm_ss";
239	  if (A.scope() == "local.fragment") {
240	    ICHECK(B.scope() != "local.fragment");
241	    op_name = "tl::gemm_rs";
242	  } else if (B.scope() == "local.fragment") {
243	    op_name = "tl::gemm_sr";
244	  }
245	  ss << op_name << "<" << M << ", " << N << ", " << K << ", ";
246	  ss << warp_m << ", " << warp_n << ", ";
247	  ss << trans_A << ", " << trans_B;
248	  ss << ", " << clear_accum;
249	  if (TargetIsCDNA(T.target)) {
250	    // for cdna gemm, we need to specify kPack
251	    ss << ", " << kPack;
252	  } else if (TargetIsHopper(T.target)) {
253	    ss << ", " << (maybe_wgmma ? "true" : "false");
254	  }
255	  if (wg_wait != 0) {
256	    ss << ", " << wg_wait;
257	  }
258	  ss << ">";
259	  auto A_buffer = T.buffer_remap.count(A) ? T.buffer_remap[A] : A;
260	  auto B_buffer = T.buffer_remap.count(B) ? T.buffer_remap[B] : B;
261	  auto C_buffer = T.buffer_remap[C];
262	
263	  Array<PrimExpr> new_args;
264	  new_args.push_back(StringImm(ss.str()));
265	  new_args.push_back(Aptr);
266	  new_args.push_back(Bptr);
267	  new_args.push_back(Cptr);
268	  auto new_call = Call(DataType::Handle(), builtin::call_extern(), new_args);
269	  return Evaluate(new_call);
270	}
