272	LayoutMap Gemm::InferLayout(const LayoutInferArgs &T, InferLevel level) {
273	  if (completed_)
274	    return {};
275	  LayoutMap results;
276	  ICHECK(C.scope() == "local.fragment");
277	  auto thread_range = T.thread_bounds;
278	  auto block_size = *as_const_int(thread_range->extent);
279	  if (TargetIsVolta(T.target)) {
280	    const int warp_size = 32;
281	    auto [warp_m, warp_n] =
282	        ComputeWarpPartition(block_size / warp_size, T.target);
283	    auto fragment =
284	        makeGemmVoltaFragmentC(M, N, M / warp_m, N / warp_n, C->dtype.bits());
285	    results.Set(C, fragment->BindThreadRange(thread_range));
286	    if (A.scope() == "shared" || A.scope() == "shared.dyn") {
287	      int dim_A = A->shape.size();
288	      results.Set(A, makeGemmVoltaABLayout(*as_const_int(A->shape[dim_A - 2]),
289	                                           *as_const_int(A->shape[dim_A - 1]),
290	                                           true, trans_A ? 1 : 2));
291	    } else if (A.scope() == "local.fragment") {
292	      ICHECK(trans_A == false);
293	      auto fragment = makeGemmVoltaFragmentA(M, N, K, M / warp_m, N / warp_n);
294	      results.Set(A, fragment->BindThreadRange(thread_range));
295	    } else {
296	      ICHECK(0);
297	    }
298	
299	    ICHECK(B.scope() == "shared" || B.scope() == "shared.dyn");
300	    int dim_B = B->shape.size();
301	    results.Set(B, makeGemmVoltaABLayout(*as_const_int(B->shape[dim_B - 2]),
302	                                         *as_const_int(B->shape[dim_B - 1]),
303	                                         false, trans_B ? 2 : 1));
304	  } else if (TargetIsAmpere(T.target) || TargetIsTuring(T.target)) {
305	    const int warp_size = 32;
306	    auto [warp_m, warp_n] =
307	        ComputeWarpPartition(block_size / warp_size, T.target);
308	    auto fragment =
309	        makeGemmFragmentC(M, N, M / warp_m, N / warp_n, C->dtype.bits());
310	    results.Set(C, fragment->BindThreadRange(thread_range));
311	
312	    if (A.scope() == "shared" || A.scope() == "shared.dyn") {
313	      int dim_A = A->shape.size();
314	      const int64_t mat_stride = *as_const_int(A->shape[dim_A - 2]);
315	      const int64_t mat_continuous = *as_const_int(A->shape[dim_A - 1]);
316	      results.Set(A,
317	                  makeGemmABLayout(mat_stride, mat_continuous, mat_continuous,
318	                                   A->dtype.bits(), trans_A ? 1 : 2));
319	    } else if (A.scope() == "local.fragment") {
320	      auto fragment = makeGemmFragmentA(M, N, K, M / warp_m, N / warp_n,
321	                                        A->dtype.bits(), trans_A);
322	      results.Set(A, fragment->BindThreadRange(thread_range));
323	    } else {
324	      ICHECK(0);
325	    }
326	    if (B.scope() == "shared" || B.scope() == "shared.dyn") {
327	      int dim_B = B->shape.size();
328	      const int64_t mat_stride = *as_const_int(B->shape[dim_B - 2]);
329	      const int64_t mat_continuous = *as_const_int(B->shape[dim_B - 1]);
330	      results.Set(B,
331	                  makeGemmABLayout(mat_stride, mat_continuous, mat_continuous,
332	                                   B->dtype.bits(), trans_B ? 2 : 1));
333	    } else if (B.scope() == "local.fragment") {
334	      auto fragment =
335	          makeGemmFragmentB(M, N, K, M / warp_m, N / warp_n, trans_B);
336	      results.Set(B, fragment->BindThreadRange(thread_range));
337	    } else {
338	      ICHECK(0);
339	    }
340	  } else if (TargetIsHopper(T.target)) {
341	    const int warp_size = 32;
342	    bool maybe_wgmma = (this->M >= 64) && (block_size / warp_size % 4 == 0);
343	    auto [warp_m, warp_n] =
344	        ComputeWarpPartition(block_size / warp_size, T.target, maybe_wgmma);
345	    auto fragment =
346	        maybe_wgmma
347	            ? makeGemmFragmentCHopper(M, N, M / warp_m, N / warp_n,
348	                                      C->dtype.bits())
349	            : makeGemmFragmentC(M, N, M / warp_m, N / warp_n, C->dtype.bits());
350	    results.Set(C, fragment->BindThreadRange(thread_range));
351	    if (A.scope() == "shared" || A.scope() == "shared.dyn") {
352	      int dim_A = A->shape.size();
353	      const int64_t mat_stride = *as_const_int(A->shape[dim_A - 2]);
354	      const int64_t mat_continuous = *as_const_int(A->shape[dim_A - 1]);
355	      const int64_t continuity =
356	          trans_A ? 4 * mat_continuous / warp_m : mat_continuous;
357	      results.Set(A,
358	                  makeGemmABLayout(mat_stride, mat_continuous, mat_continuous,
359	                                   A->dtype.bits(), trans_A ? 1 : 2));
360	    } else {
361	      auto fragment = makeGemmFragmentA(M, N, K, M / warp_m, N / warp_n,
362	                                        A->dtype.bits(), trans_A);
363	      results.Set(A, fragment->BindThreadRange(thread_range));
364	    }
365	    if (B.scope() == "shared" || B.scope() == "shared.dyn") {
366	      int dim_B = B->shape.size();
367	      const int64_t mat_stride = *as_const_int(B->shape[dim_B - 2]);
368	      const int64_t mat_continuous = *as_const_int(B->shape[dim_B - 1]);
369	      const int64_t continuity =
370	          trans_B ? mat_continuous : mat_continuous / warp_n;
371	      results.Set(B, makeGemmABLayout(mat_stride, mat_continuous, continuity,
372	                                      B->dtype.bits(), trans_B ? 2 : 1));
373	    } else {
374	      ICHECK(0) << "WGMMA only support B in shared.";
375	    }
376	  } else if (TargetIsCDNA(T.target)) {
377	    const int warp_size = 64;
378	    auto [warp_m, warp_n] =
379	        ComputeWarpPartition(block_size / warp_size, T.target);
380	
381	    auto fragment =
382	        makeGemmFragmentCCDNA(M, N, M / warp_m, N / warp_n, C->dtype.bits());
383	    results.Set(C, fragment->BindThreadRange(thread_range));
384	
385	    if (A.scope() == "shared" || A.scope() == "shared.dyn") {
386	      int dim_A = A->shape.size();
387	      auto shared_layout = makeGemmABLayoutCDNA(
388	          *as_const_int(A->shape[dim_A - 2]),
389	          *as_const_int(A->shape[dim_A - 1]), A->dtype.bits(), kPack);
390	      results.Set(A, shared_layout);
391	    } else if (A.scope() == "local.fragment") {
392	      auto fragment = makeGemmFragmentACDNA(M, N, K, M / warp_m, N / warp_n,
393	                                            A->dtype.bits(), trans_A);
394	      results.Set(A, fragment->BindThreadRange(thread_range));
395	    } else {
396	      ICHECK(0);
397	    }
398	    if (B.scope() == "shared" || B.scope() == "shared.dyn") {
399	      int dim_B = B->shape.size();
400	      auto shared_layout = makeGemmABLayoutCDNA(
401	          *as_const_int(B->shape[dim_B - 2]),
402	          *as_const_int(B->shape[dim_B - 1]), B->dtype.bits(), kPack);
403	
404	      results.Set(B, shared_layout);
405	    } else if (B.scope() == "local.fragment") {
406	      auto fragment =
407	          makeGemmFragmentB(M, N, K, M / warp_m, N / warp_n, trans_B);
408	      results.Set(B, fragment->BindThreadRange(thread_range));
409	    } else {
410	      ICHECK(0);
411	    }
412	  } else {
413	    ICHECK(0) << "Not supported " << T.target->str();
414	  }
415	  completed_ = true;
416	  return results;
417	}
