238	      // The column dim is a COMPILE-TIME template arg. A runtime inner-extent
239	      // slice (dynamic width, e.g. a softmax's actual window tw_a < buffer
240	      // width) would put a non-const expr in the template -> invalid C++ ("use
241	      // of undeclared identifier"). Use the buffer's compile-time shape for the
242	      // template; the runtime width is already carried by the maskShapeN
243	      // function arg (validCol_dst). A const extent stays byte-identical (==
244	      // shape for a full copy, or the const slice width), so every existing
245	      // caller is unchanged -- only the previously-uncompilable runtime-slice
246	      // case changes.
247	      PrimExpr gm2ub_tmpl_n = dst_extents[dst->shape.size() - 1];
248	      if (!gm2ub_tmpl_n->IsInstance<IntImmNode>()) {
249	        gm2ub_tmpl_n = dst->shape[dst->shape.size() - 1];
250	        // The shape fallback must itself be a compile-time constant; a buffer
251	        // declared with a dynamic inner dim would still emit a non-const
252	        // template arg (the invalid-C++ case above), so fail early and clearly.
253	        ICHECK(gm2ub_tmpl_n->IsInstance<IntImmNode>())
254	            << "copy_gm_to_ub: the inner (column) dimension of the destination "
255	               "buffer shape must be a compile-time constant, but got "
256	            << gm2ub_tmpl_n;
257	      }
258	      ss << gm2ub_tmpl_n;
259	      if (dst->shape.size() > 1) {
260	        ss << ", " << compute_blocklen(dst, dst_extents);
261	      }
262	      ss << ">";
263	    } else if (dst.scope() == "global") {
264	      config.ub2gm = true;
265	      strideN = compute_strideN(dst, dst_extents);
266	      config.needs_strideN = true;
267	
268	      ss << "copy_ub_to_gm<";
269	      ss << get_dtype(dst) << ", ";
270	      // See copy_gm_to_ub above: a runtime inner-extent must use the buffer's
271	      // compile-time shape for the template col dim (runtime width is carried
272	      // by the maskShapeN function arg); const extents are byte-identical.
273	      PrimExpr ub2gm_tmpl_n = src_extents[src->shape.size() - 1];
274	      if (!ub2gm_tmpl_n->IsInstance<IntImmNode>()) {
275	        ub2gm_tmpl_n = src->shape[src->shape.size() - 1];
276	        // See copy_gm_to_ub: the shape fallback must itself be compile-time.
277	        ICHECK(ub2gm_tmpl_n->IsInstance<IntImmNode>())
278	            << "copy_ub_to_gm: the inner (column) dimension of the source "
279	               "buffer shape must be a compile-time constant, but got "
280	            << ub2gm_tmpl_n;
281	      }
282	      ss << ub2gm_tmpl_n;
283	      if (src->shape.size() > 1) {
284	        ss << ", " << compute_blocklen(src, src_extents);
285	      }
286	      ss << ">";
287	    } else if (dst.scope() == "shared.l1") {
288	      config.virtual_channel = true;
289	      ss << "copy_ub_to_l1<";
290	      ss << get_dtype(dst) << ", ";
291	      ss << src_extents[src->shape.size() - 1];
292	      if (src->shape.size() > 1) {
293	        ss << ", " << compute_blocklen(src, src_extents);
294	      }
295	      ss << ">";
296	    } else if (src.scope() == "wmma.accumulator") {
297	      config.virtual_channel = true;
298	      ss << "copy_l0c_to_ub<";
299	      ss << get_dtype(src) << ", " << get_dtype(dst) << ", ";
300	      ss << "layout::RowMajor, "; // In "ub -> gm -> l1" path, gm is
301	                                  // always row major
302	      ss << src->shape[src->shape.size() - 2] << ", "
303	         << src->shape[src->shape.size() - 1];
304	      ss << ", " << enRelu << ">";
305	    } else {
306	      PrimExpr len = 1;
307	      for (auto &shape : dst_extents) {
308	        len *= shape;
309	      }
310	      ss << "copy_ub_to_ub<" << get_dtype(dst) << ", " << get_dtype(src) << ", "
311	         << len << ">";
312	      config.ub2ub = true;
313	    }
314	  } else {
315	    LOG(FATAL) << "Unsupported scope: src = " << src.scope()
316	               << ", dst = " << dst.scope();
317	  }
318	
319	  if (!config.print_ub) {
320	    ss << "<" << get_dtype(src) << ", ";
321	
322	    if (config.l0c2gm) {
323	      ss << get_dtype(dst) << ", ";
324	    }
325	
326	    if (config.print_gm_layout) {
327	      ss << (T.layout_map.count(src) ? T.layout_map[src]->AscendLayoutStr()
328	                                     : "layout::RowMajor")
329	         << ", ";
330	    }
331	
332	    if (config.print_src_layout) {
333	      ICHECK(T.layout_map.count(src))
334	          << "Layout map does not contain source buffer: " << src->name;
335	      ss << T.layout_map[src]->AscendLayoutStr() << ", ";
336	    } else if (config.print_dst_layout) {
337	      ICHECK(T.layout_map.count(dst))
338	          << "Layout map does not contain destination buffer: " << dst->name;
339	      ss << T.layout_map[dst]->AscendLayoutStr() << ", ";
340	    }
341	
342	    int src_ndim = src->shape.size(), dst_ndim = dst->shape.size();
343	
344	    if (dst.scope() == "global") {
345	      ss << src->shape[src_ndim - 2] << ", " << src->shape[src_ndim - 1];
346	      if (config.l0c2gm) {
347	        ss << ", " << enRelu;
348	      }
349	      ss << ">";
350	    } else if (src.scope() == "global") {
351	      ss << dst->shape[dst_ndim - 2] << ", " << dst->shape[dst_ndim - 1] << ">";
352	    } else {
353	      ss << src->shape[src_ndim - 2] << ", " << src->shape[src_ndim - 1];
354	      if (config.l12l0) {
355	        transposeL1 == 0 ? ss << ", false" << ">" : ss << ", true" << ">";
356	      }
357	      // ss << src->shape[src_ndim - 2] << ", " << src->shape[src_ndim - 1] <<
358	      // ", "
359	      //    << dst->shape[dst_ndim - 2] << ", " << dst->shape[dst_ndim - 1] <<
360	      //    ">";
361	    }
362	  }
363	
364	  auto src_indices = build_indices(src_range);
365	  auto dst_indices = build_indices(dst_range);
366	
367	  auto src_new_indices = T.layout_map.count(src)
368	                             ? T.layout_map[src]->Forward(src_indices)
369	                             : src_indices;
370	  auto dst_new_indices = T.layout_map.count(dst)
371	                             ? T.layout_map[dst]->Forward(dst_indices)
372	                             : dst_indices;
373	
374	  auto src_new_buffer = T.buffer_remap.count(src) ? T.buffer_remap[src] : src;
375	  auto dst_new_buffer = T.buffer_remap.count(dst) ? T.buffer_remap[dst] : dst;
376	
377	  PrimExpr src_len = 1;
378	  for (auto &shape : src_extents) {
379	    src_len *= shape;
380	  }
381	
382	  PrimExpr dst_len = 1;
383	  for (auto &shape : dst_extents) {
384	    dst_len *= shape;
385	  }
386	
387	  auto src_ptr = src_new_buffer.access_ptr(
388	      1, src_new_buffer->dtype, 1,
389	      src_new_buffer.OffsetOf(src_new_indices).back(), src_len);
390	  auto dst_ptr = dst_new_buffer.access_ptr(
391	      2, dst_new_buffer->dtype, 1,
392	      dst_new_buffer.OffsetOf(dst_new_indices).back(), dst_len);
393	
394	  PrimExpr tmp_ptr;
395	  if (tmp.defined()) {
396	    auto tmp_new_indices =
397	        T.layout_map.count(tmp)
398	            ? T.layout_map[tmp]->Forward(build_indices(tmp_range))
399	            : build_indices(tmp_range);
400	    auto tmp_new_buffer = T.buffer_remap.count(tmp) ? T.buffer_remap[tmp] : tmp;
401	    PrimExpr tmp_len = 1;
402	    for (auto &shape : tmp_extents) {
403	      tmp_len *= shape;
404	    }
405	    tmp_ptr = tmp_new_buffer.access_ptr(
406	        3, tmp_new_buffer->dtype, 1,
407	        tmp_new_buffer.OffsetOf(tmp_new_indices).back(), tmp_len);
408	  }
409	
410	  auto compute_valid_extent = [](PrimExpr min_val, PrimExpr extent,
411	                                 PrimExpr shape) -> PrimExpr {
412	    PrimExpr remaining = shape - min_val;
413	    if (remaining.dtype().lanes() > 1) {
414	      return extent;
415	    }
416	    return Select(remaining >= extent, extent,
417	                  Select(remaining > 0, remaining, 0));
418	  };
419	
420	  auto find_active_dim_indices =
421	      [](const Array<PrimExpr> &extents) -> std::vector<int> {
422	    std::vector<int> active_indices;
423	    int size = static_cast<int>(extents.size());
424	
425	    // Traverse from 0 to size-1, find dimensions where extent != 1
426	    for (int i = 0; i < size; ++i) {
427	      if (auto *int_imm = extents[i].as<IntImmNode>()) {
428	        if (int_imm->value != 1) {
429	          active_indices.push_back(i);
430	        }
431	      } else {
432	        active_indices.push_back(i);
433	      }
434	    }
435	
436	    // The last dimension must always be included in the result
437	    if (size >= 1 &&
438	        (active_indices.empty() || active_indices.back() != size - 1)) {
439	      active_indices.push_back(size - 1);
440	    }
441	
442	    // Special: If extents.size() >= 2 and active_indices.size() == 1,
443	    // insert size-2 at the second-to-last position
444	    if (size >= 2 && active_indices.size() == 1) {
445	      active_indices.insert(active_indices.begin(), size - 2);
446	    }
447	
448	    return active_indices;
449	  };
450	
451	  PrimExpr validRow_src, validCol_src, validRow_dst, validCol_dst;
452	
453	  // src: compute validRow and validCol using active dimension indices
454	  std::vector<int> src_active = find_active_dim_indices(src_extents);
455	  if (src_active.size() >= 2) {
456	    int row_idx = src_active[src_active.size() - 2];
457	    int col_idx = src_active.back();
458	    validRow_src =
459	        compute_valid_extent(src_range[row_idx]->min,
460	                             src_range[row_idx]->extent, src->shape[row_idx]);
461	    validCol_src =
462	        compute_valid_extent(src_range[col_idx]->min,
463	                             src_range[col_idx]->extent, src->shape[col_idx]);
464	  } else if (src_active.size() == 1) {
465	    int col_idx = src_active[0];
466	    validRow_src = Integer(1);
467	    validCol_src =
468	        compute_valid_extent(src_range[col_idx]->min,
469	                             src_range[col_idx]->extent, src->shape[col_idx]);
470	  } else {
471	    validRow_src = 0;
472	    validCol_src = 0;
473	  }
474	
475	  // dst: compute validRow and validCol using active dimension indices
476	  std::vector<int> dst_active = find_active_dim_indices(dst_extents);
477	  if (dst_active.size() >= 2) {
478	    int row_idx = dst_active[dst_active.size() - 2];
479	    int col_idx = dst_active.back();
480	    validRow_dst =
481	        compute_valid_extent(dst_range[row_idx]->min,
482	                             dst_range[row_idx]->extent, dst->shape[row_idx]);
483	    validCol_dst =
484	        compute_valid_extent(dst_range[col_idx]->min,
485	                             dst_range[col_idx]->extent, dst->shape[col_idx]);
486	  } else if (dst_active.size() == 1) {
487	    int col_idx = dst_active[0];
488	    validRow_dst = Integer(1);
489	    validCol_dst =
490	        compute_valid_extent(dst_range[col_idx]->min,
491	                             dst_range[col_idx]->extent, dst->shape[col_idx]);
492	  } else {
493	    validRow_dst = 0;
494	    validCol_dst = 0;
495	  }
496	
497	  Array<PrimExpr> new_args;
498	  new_args.push_back(StringImm(ss.str()));
499	  new_args.push_back(src_ptr);
500	  new_args.push_back(dst_ptr);
501	
502	  if (config.needs_strideN) {
503	    new_args.push_back(strideN);
504	  }
505	
506	  if (config.l0_dst_split) {
507	    int dst_dim = dst->shape.size();
508	    PrimExpr dm = dst->shape[dst_dim - 2];
509	    PrimExpr dn = dst->shape[dst_dim - 1];
510	    // realK overrides the L0 fractal's K extent so it matches the following
511	    // mma's runtime K. K is the trailing dim for matrix_a ([M, K]) and the
512	    // leading one for matrix_b ([K, N]). realK == 0 keeps dst->shape, which is
513	    // byte-identical for every existing L1->L0 copy.
514	    const auto *rk_imm = realK.as<IntImmNode>();
515	    if (!(rk_imm && rk_imm->value == 0)) {
516	      if (dst.scope() == "wmma.matrix_a") {
517	        dn = realK;
518	      } else if (dst.scope() == "wmma.matrix_b") {
519	        dm = realK;
520	      }
521	    }
522	    // realN overrides matrix_b's N extent, the axis realK does not cover.
523	    const auto *rn_imm = realN.as<IntImmNode>();
524	    if (!(rn_imm && rn_imm->value == 0) && dst.scope() == "wmma.matrix_b") {
525	      dn = realN;
526	    }
527	    new_args.push_back(dm);
528	    new_args.push_back(dn);
529	  }
530	
531	  if (config.l0c2gm) {
532	    new_args.push_back(compute_strideN(dst, dst_extents));
533	    new_args.push_back(validRow_dst);
534	    new_args.push_back(validCol_dst);
535	    new_args.push_back(src->shape[src->shape.size() - 2]);
536	    new_args.push_back(src->shape[src->shape.size() - 1]);
537	    new_args.push_back(Bool(enRelu)); // Add enable_relu parameter
538	    // unitFlag goes last, not in call order: this list is shared with the PTO
539	    // codegen, which reads several of these by position (the pad enum and the
540	    // relu flag among them). The ascendc codegen picks it up off the end and
541	    // emits it in the position the C++ helper expects.
542	    new_args.push_back(unitFlag);
543	  }
544	
545	  if (config.gm2l1) {
546	    new_args.push_back(compute_strideN(src, src_extents));
547	    new_args.push_back(validRow_src);
548	    new_args.push_back(validCol_src);
549	    new_args.push_back(dst->shape[dst->shape.size() - 2]);
550	    new_args.push_back(dst->shape[dst->shape.size() - 1]);
551	  }
552	
553	  if (config.gm2ub) {
554	    new_args.push_back(validRow_src);
555	    new_args.push_back(validCol_src);
556	    PrimExpr pad_val = padValue;
557	    if (pad_val->dtype != dst->dtype) {
558	      pad_val = Cast(dst->dtype, pad_val);
559	    }
560	    new_args.push_back(pad_val);
561	    // Physical UB tile dims (row pitch). These trail pad_val and are consumed
562	    // by AscendTailMaskPropagation to model the tail rect; CopyCodegen prints
563	    // only the first 4 extra args (strideN, validRow, validCol, pad_val).
564	    if (dst->shape.size() > 1) {
565	      new_args.push_back(dst->shape[dst->shape.size() - 2]);
566	    }
567	    new_args.push_back(dst->shape[dst->shape.size() - 1]);
568	  }
569	
570	  if (config.ub2gm) {
571	    new_args.push_back(validRow_dst);
572	    new_args.push_back(validCol_dst);
573	    if (src->shape.size() > 1) {
574	      new_args.push_back(src->shape[src->shape.size() - 2]);
575	    }
576	    new_args.push_back(src->shape[src->shape.size() - 1]);
577	  }
578	
579	  if (config.virtual_channel) {
580	    new_args.push_back(src_extents[src_extents.size() - 1]); // src_N
581	    if (src_extents.size() >= 2) {
582	      new_args.push_back(src_extents[src_extents.size() - 2]); // src_M
583	    } else {
584	      new_args.push_back(IntImm(DataType::Int(32), 0)); // 1D: no M dim
585	    }
586	    new_args.push_back(dst_extents[dst_extents.size() - 2]); // dst_M
587	    new_args.push_back(dst_extents[dst_extents.size() - 1]); // dst_N
588	    // Add tmp buffer for UB->L1 copy on A5 (for ND->Nz conversion)
589	    if (tmp.defined()) {
590	      new_args.push_back(tmp_ptr);
591	      new_args.push_back(tmp_extents[tmp_extents.size() - 2]); // tmp_M
592	      new_args.push_back(tmp_extents[tmp_extents.size() - 1]); // tmp_N
593	    }
594	  }
595	
596	  if (config.ub2ub) {
597	    PrimExpr src_tile_rows = src_extents.size() >= 2
598	                                 ? src_extents[src_extents.size() - 2]
599	                                 : Integer(1);
600	    PrimExpr src_tile_cols = src_extents[src_extents.size() - 1];
601	    PrimExpr src_buf_cols = src->shape[src->shape.size() - 1];
602	    PrimExpr dst_tile_rows = dst_extents.size() >= 2
603	                                 ? dst_extents[dst_extents.size() - 2]
604	                                 : Integer(1);
605	    PrimExpr dst_tile_cols = dst_extents[dst_extents.size() - 1];
606	    PrimExpr dst_buf_cols = dst->shape[dst->shape.size() - 1];
607	    new_args.push_back(src_tile_rows);
608	    new_args.push_back(src_tile_cols);
609	    new_args.push_back(src_buf_cols);
610	    new_args.push_back(dst_tile_rows);
611	    new_args.push_back(dst_tile_cols);
612	    new_args.push_back(dst_buf_cols);
613	  }
614	  // if (config.l12l0) {
615	  //   ICHECK(src->shape.size() == dst->shape.size());
616	  //   bool is_extract = false;
617	  //   auto dst_shape_size = dst->shape.size();
618	  //   auto src_shape_size = src->shape.size();
619	  //   for (int i = dst_shape_size - 1; i >= dst_shape_size - 2; i--) {
620	  //     if (i == -1) {
621	  //         break;
622	  //     }
623	  //     // std::cout << "dst_shape_size -2 = " << dst_shape_size - 2  << ", i =
624	  //     " << i << ", dst->shape: " << dst->shape[i]
625	  //     //   << "src->shape: " << src->shape[i] << "\n";
626	  //     if (src->shape[i].as<IntImmNode>()->value !=
627	  //     dst->shape[i].as<IntImmNode>()->value) {
628	  //         is_extract = true;
629	  //     }
630	  //     new_args.push_back(src_indices[i]);
631	  //   }
632	  //   new_args.push_back(Bool(is_extract));
633	  //   auto dst_var = dst_ptr.as<CallNode>()->args[1];
634	  //   std::cout << "newargs in copy to l1: " << new_args << "\n";
635	  //   std::cout << "src_indices: " << src_indices << "\n";
636	  // }
637	
638	  auto new_call = Call(DataType::Handle(), builtin::call_extern(), new_args);
639	  return Evaluate(new_call);
640	}
