2485	void CodeGenTileLangAscend::GemmOpCodegen(const CallNode *op) {
2486	  std::string op_name =
2487	      "tl::ascend::" + Downcast<StringImm>(op->args[0])->value;
2488	
2489	  this->PrintIndent();
2490	  auto a_var = op->args[1].as<CallNode>()->args[1].as<VarNode>();
2491	  auto b_var = op->args[2].as<CallNode>()->args[1].as<VarNode>();
2492	  auto c_var = op->args[3].as<CallNode>()->args[1].as<VarNode>();
2493	
2494	  auto a_offset = PrintExpr(op->args[1].as<CallNode>()->args[2]);
2495	  auto b_offset = PrintExpr(op->args[2].as<CallNode>()->args[2]);
2496	  auto c_offset = PrintExpr(op->args[3].as<CallNode>()->args[2]);
2497	
2498	  auto a_name = var_idmap_[a_var];
2499	  auto b_name = var_idmap_[b_var];
2500	  auto c_name = var_idmap_[c_var];
2501	
2502	  this->stream << op_name << "(" << a_name << "[" << a_offset << "], " << b_name
2503	               << "[" << b_offset << "], " << c_name << "[" << c_offset
2504	               << "], ascend_l0a, ascend_l0b, " << PrintExpr(op->args[4])
2505	               << ", " << PrintExpr(op->args[5]) << ");\n";
2506	}
