2508	void CodeGenTileLangAscend::PrintfOpCodegen(const CallNode *op,
2509	                                            const std::string &op_name) {
2510	  this->PrintIndent();
2511	  this->stream << op_name << "(";
2512	  for (size_t i = 0; i < op->args.size(); ++i) {
2513	    if (i > 0) {
2514	      this->stream << ", ";
2515	    }
2516	    if (auto *arg = op->args[i].as<CallNode>()) {
2517	      if (arg->op.same_as(builtin::tvm_access_ptr())) {
2518	        this->stream << PrintBufferOffset(arg, false) << ".GetPhyAddr()";
2519	      } else {
2520	        std::cout
2521	            << "CallNode with builtin::tvm_access_ptr is requested, but got "
2522	            << op->args[i] << ".\n";
2523	      }
2524	    } else {
2525	      this->stream << PrintExpr(op->args[i]);
2526	    }
2527	  }
2528	  this->stream << ");\n";
2529	}
