2531	void CodeGenTileLangAscend::DumpTensorCodegen(const CallNode *op) {
2532	  AddDeclStream(decl_stream, "#include \"tl_templates/ascend/printf.h\"\n");
2533	  this->PrintIndent();
2534	  this->stream << "tl::ascend::DumpTensor"
2535	               << "(";
2536	
2537	  // 0. Bufferָ��
2538	  this->stream << PrintBufferOffset(op->args[0].as<CallNode>()) << ",";
2539	  // 1. desc
2540	  this->stream << PrintExpr(op->args[1]) << ", ";
2541	  // 2. dump_size
