  if (const auto *ramp = dst_offset_expr.as<RampNode>()) {
    dst_offset_expr = ramp->base;
  }
  auto src_offset = PrintExpr(src_offset_expr);
  auto dst_offset = PrintExpr(dst_offset_expr);

